urlset:
{% comment %}
  Teil-Sitemaps mit Bildauszeichnung (TS19, 01.10.2026). Wie Djangos
  sitemap.xml, dazu der image:-Namensraum und je  die Knoten aus
  url.bilder (sitemaps.MitBildern). Sitemaps ohne Bilder liefern eine leere
  Liste, ihre Ausgabe bleibt unveraendert. Kein eigenes Zeilenlayout:
  {% spaceless %} haelt die Datei klein (Seitengewicht).
{% endcomment %}
{% spaceless %}
{% for url in urlset %}

    {{ url.location }}
    {% if url.lastmod %}{{ url.lastmod|date:"Y-m-d" }}{% endif %}
    {% if url.changefreq %}{{ url.changefreq }}{% endif %}
    {% if url.priority %}{{ url.priority }}{% endif %}
    {% for alternate in url.alternates %}

    {% endfor %}
    {% for bild in url.bilder %}{{ bild.loc }}{{ bild.titel }}{% endfor %}

{% endfor %}
{% endspaceless %}
